def ref_is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def ref_intersection(a, b) -> str:
    l = max(a[0], b[0])
    r = min(a[1], b[1])
    if l > r:
        return "NO"
    length = r - l
    return "YES" if ref_is_prime(length) else "NO"


def test_containment_preserves_length():
    # (1,10) intersect (3,7) = (3,7) length 4 -> not prime
    assert intersection((1, 10), (3, 7)) == "NO"
    # (1,10) intersect (3,6) = (3,6) length 3 -> prime
    assert intersection((1, 10), (3, 6)) == "YES"
